css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-customer {
  top: 67.5mm;
  left: 35mm;
  width: 55mm;
}

.field-customer-name {
  top: 72.5mm;
  left: 25mm;
  width: 80mm;
}

.field-customer-address {
  top: 77.5mm;
  left: 25mm;
  width: 90mm;
  min-height: 20mm;
}

.field-ref-document {
  top: 107mm;
  left: 32mm;
  width: 90mm;
}

.field-document-name {
  top: 67.5mm;
  left: 130mm;
  width: 45mm;
}

.field-posting-date {
  top: 74mm;
  left: 130mm;
  width: 45mm;
}

.field-credit-term {
  top: 87mm;
  left: 145mm;
  width: 45mm;
}

.field-due-date {
  top: 87mm;
  left: 175mm;
  width: 45mm;
}

.field-sales-order-no {
  top: 93.5mm;
  left: 145mm;
  width: 45mm;
}

.field-sales-person {
  top: 55mm;
  left: 145mm;
  width: 45mm;
}

.field-territory {
  top: 108mm;
  left: 145mm;
  width: 45mm;
}

.item-table-wrapper {
  position: absolute;
  top: 123mm;
  left: 20mm;
  width: 180mm;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table th,
.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.25;
}

.col-no {
  width: 10mm;
  text-align: center;
}

.col-item {
  width: 75mm;
  text-align: left;
}

.col-qty {
  width: 25mm;
  text-align: right;
}

.col-rate {
  width: 23mm;
  text-align: right;
}

.col-discount {
  width: 17mm;
  text-align: right;
}

.col-amount {
  width: 27mm;
  text-align: right;
}

.field-gross-amount {
  top: 205mm;
  left: 150mm;
  width: 40mm;
  text-align: right;
}

.field-less-discount {
  top: 212mm;
  left: 150mm;
  width: 40mm;
  text-align: right;
}

.field-after-discount {
  top: 218mm;
  left: 150mm;
  width: 40mm;
  text-align: right;
}

.field-vat {
  top: 225mm;
  left: 150mm;
  width: 40mm;
  text-align: right;
}

.field-total-amount {
  top: 235mm;
  left: 150mm;
  width: 40mm;
  text-align: right;
  font-weight: bold;
}

.field-amount-text {
  top: 235mm;
  left: 60mm;
  width: 120mm;
}

.field-submit-by {
  top: 275mm;
  left: 145mm;
  width: 45mm;
  text-align: center;
}

html:
{% set backgrounds = [
  "/assets/connect_diagnostics_core/images/print_formats/abbreviated-tax-invoice-receipt-1.1.png",
  "/assets/connect_diagnostics_core/images/print_formats/abbreviated-tax-invoice-receipt-1.2.png",
  "/assets/connect_diagnostics_core/images/print_formats/abbreviated-tax-invoice-receipt-2.1.png",
  "/assets/connect_diagnostics_core/images/print_formats/abbreviated-tax-invoice-receipt-2.2.png"
] %}


{% set sales_orders = [] %}
{% set delivery_notes = [] %}

{% for row in doc.items %}
  {% if row.sales_order and row.sales_order not in sales_orders %}
    {% set _ = sales_orders.append(row.sales_order) %}
  {% endif %}

  {% if row.delivery_note and row.delivery_note not in delivery_notes %}
    {% set _ = delivery_notes.append(row.delivery_note) %}
  {% endif %}
{% endfor %}

{% set ref_documents = [] %}

{% for so in sales_orders %}
  {% set _ = ref_documents.append("Sales Order: " ~ so) %}
{% endfor %}

{% for dn in delivery_notes %}
  {% set _ = ref_documents.append("Delivery Note: " ~ dn) %}
{% endfor %}

{% if doc.return_against %}
  {% set _ = ref_documents.append("Return Against: " ~ doc.return_against) %}
{% endif %}

{% if doc.amended_from %}
  {% set _ = ref_documents.append("Amended From: " ~ doc.amended_from) %}
{% endif %}

{% set sales_persons = [] %}
{% for sp in doc.sales_team %}
  {% if sp.sales_person and sp.sales_person not in sales_persons %}
    {% set _ = sales_persons.append(sp.sales_person) %}
  {% endif %}
{% endfor %}


{% set print_date = frappe.db.get_value("Customer", doc.customer, "print_date") if doc.customer else 1 %}

{% for background in backgrounds %}
  <div
    class="print-page"
    style="--page-bg: url('{{ background }}');"
  >

    <!-- Customer -->
    <div class="field field-customer">
      {{ doc.customer or "" }}
    </div>

    <div class="field field-customer-name">
      {{ doc.customer_name or "" }}
    </div>

    <div class="field field-customer-address">
      {{ (doc.address_display or "") | safe }}
    </div>

    <!-- Document info -->
    <div class="field field-ref-document">
      {{ ref_documents | join(", ") }}
    </div>

    <div class="field field-document-name">
      {{ doc.name }}
    </div>

    <div class="field field-posting-date">
      {% if print_date %}{{ frappe.format_date(doc.posting_date, "dd-MM-yyyy") }}{% endif %}
    </div>

    <div class="field field-credit-term">
      {{ doc.payment_terms_template or doc.credit_terms or 0 }}
    </div>

    <div class="field field-due-date">
      {{ frappe.format_date(doc.due_date, "dd-MM-yyyy") if doc.due_date else "" }}
    </div>

    <div class="field field-sales-order-no">
      {{ sales_orders | join(", ") }}
    </div>

    <div class="field field-sales-person">
      {{ sales_persons | join(", ") }}
    </div>

    <div class="field field-territory">
      {{ doc.territory or "" }}
    </div>

    <!-- Item table -->
    <div class="item-table-wrapper">
      <table class="item-table">
        <tbody>
          {% for row in doc.items %}
            <tr>
              <td class="col-no">
                {{ loop.index }}
              </td>

              <td class="col-item">
                {{ row.item_code }} : {{ row.item_name }}
              </td>

              <td class="col-qty">
                {{ frappe.format(row.qty, {"fieldtype": "Float"}) }}
              </td>

              <td class="col-rate">
                {{ print_currency(row.rate + (row.discount_amount if row.discount_amount > 0 else 0), doc.currency) }}
              </td>

              <td class="col-discount">
                {% set line_discount = (row.discount_amount if row.discount_amount > 0 else 0) * row.qty %}
                {% if line_discount %}
                  {{ print_currency(line_discount, doc.currency) }}
                {% else %}
                  -
                {% endif %}
              </td>

              <td class="col-amount">
                {{ print_currency(row.amount, doc.currency) }}
              </td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>

    <!-- Totals -->
    <div class="field field-gross-amount">
      {{ print_currency(doc.total, doc.currency) }}
    </div>

    <div class="field field-less-discount">
      {{ print_currency(doc.discount_amount or 0, doc.currency) }}
    </div>

    <div class="field field-after-discount">
      {{ print_currency(doc.net_total, doc.currency) }}
    </div>

    <div class="field field-vat">
      {{ print_currency(doc.total_taxes_and_charges or 0, doc.currency) }}
    </div>

    <div class="field field-total-amount">
      {{ print_currency(doc.grand_total, doc.currency) }}
    </div>

    <div class="field field-amount-text">
      ({{ number_to_thai_currency(doc.grand_total, doc.currency) }}).
    </div>

    <div class="field field-submit-by">
      {% if doc.docstatus == 1 %}{{ doc.modified_by or "" }}{% endif %}
    </div>

  </div>
{% endfor %}
